                        + "(activity_id, utc_date, utc_hour, reserved_count, "
                        + "confirmed_count, cancelled_count, expired_count) "
                        + "SELECT ?, ?, ?, 0, 0, 0, 0 WHERE NOT EXISTS ("
                        + "SELECT 1 FROM activity_hour_ledger "
                        + "WHERE activity_id = ? AND utc_date = ? AND utc_hour = ?)",
