 * 申请预占前按活动结算，确保其他公告的过期名额也已归还到同一小时账。
 * 历史无活动归属（activity_id 为 NULL）的单据不参与活动结算。
 */
public List<Reservation> lockExpiredReservedByActivity(String activityId, long nowUtc) {
    return jdbc.query("SELECT " + COLUMNS + " FROM exposure_reservation "
                    + "WHERE activity_id = ? AND status = 'RESERVED' AND expires_at_utc <= ? FOR UPDATE",
            MAPPER, activityId, nowUtc);
}

/**
 * 行锁查询属于指定公告或指定活动的全部已到期 RESERVED 预占单（一次查询取齐全部行锁）。
 * 申请预占前结算使用：既释放本公告跨迁移（旧活动/无活动）到期单的公告/访客额度，
 * 也释放同活动其他公告到期单的小时名额。调用方必须在本查询返回后再更新任何额度账，
 * 以保持“先取齐预占单行锁、再锁额度账”的加锁顺序。
 */
public List<Reservation> lockExpiredForCampaignOrActivity(String campaignId,
                                                          String activityId, long nowUtc) {
    return jdbc.query("SELECT " + COLUMNS + " FROM exposure_reservation "
                    + "WHERE status = 'RESERVED' AND expires_at_utc <= ? "
                    + "AND (campaign_id = ? OR activity_id = ?) FOR UPDATE",
            MAPPER, nowUtc, campaignId, activityId);
}

