    @DisplayName("日结快照：往日首次查询固化确认/取消数，之后改配不改写；当日为实时视图")
    void dailySettlement_freezesAndDoesNotRewrite() {
        // h9 预算 1、h10 预算 3
        createActivity("req-a", "act", budgets(9, 1, 10, 3));
        createCampaignInActivity("req-c", "c1", "act");

        // 9 点：1 单确认
